sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    gs.info("[Alert BR] Triggered for Alert in APP: " + current.sys_id);

    var eventGR = new GlideRecord("em_event");

    if (!gs.nil(current.sn_source_event_id)) {
        // Best case: match by source event ID
        eventGR.addQuery("source_event_id", current.sn_source_event_id);
    } else {
        // matching by common fields
        eventGR.addQuery("node", current.node);
        eventGR.addQuery("resource", current.resource);
        eventGR.addQuery("event_class", current.event_class);
    }

    eventGR.orderByDesc("sys_created_on");
    eventGR.setLimit(1);

    eventGR.query();
    if (eventGR.next()) {
        gs.info("[Alert BR] Found matching Event: " + eventGR.sys_id);

        current.u_rule_name = eventGR.u_rule_name;
        current.u_api_key = eventGR.u_api_key;

        gs.info("[Alert BR] Values copied → u_rule_name=" + current.u_rule_name + ", u_api_key=" + current.u_api_key);
    } else {
        gs.warn("[Alert BR] No matching Event found for Alert: " + current.sys_id);
    }

})(current, previous);
